/**
 * Response guards for the Automation Intelligence API (DOCB-14197).
 *
 * These endpoints are org-admin gated, and an auth failure on this route can
 * RESOLVE with an error payload ({detail: "..."} or {}) instead of throwing.
 * A shallow "is it an object" check lets such a payload through, and the UI
 * then renders a confident 0% / empty timeline that is indistinguishable from
 * a real, terrible result. Every guard below therefore validates the nested
 * members the screens actually read, so a malformed body always lands in an
 * error state rather than in an empty-success rendering.
 */

import type {
  TouchlessSummaryResponse,
  TouchlessTrendResponse,
  TouchlessSupplierOpportunitiesResponse,
  TouchlessSupplierDiagnosisResponse,
  TouchlessDocumentTraceResponse,
} from 'src/services/analytics/TouchlessService';

/** Default Pure Touchless target in percent, used only when the API omits one. */
export const TOUCHLESS_DEFAULT_TARGET_PCT = 70;

/**
 * `typeof [] === 'object'`, so a bare `typeof x === 'object'` check accepts an
 * array — which would let `{buckets: []}` pass as a bucket map.
 */
export function isPlainObject(
  value: unknown,
): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0;
}

/**
 * A string with something actually IN it.
 *
 * Distinct from `isNonEmptyString`, which only asks whether the string exists:
 * used where the value has to be readable on screen, and whitespace is not.
 */
function hasText(value: unknown): value is string {
  return typeof value === 'string' && value.trim().length > 0;
}

/**
 * A field the payload may omit entirely. `undefined` and `null` both pass;
 * anything present must satisfy the predicate. Used for fields the UI renders
 * with a fallback rather than requiring.
 */
function isOptional(
  value: unknown,
  predicate: (item: unknown) => boolean,
): boolean {
  return value === undefined || value === null || predicate(value);
}

function isString(value: unknown): boolean {
  return typeof value === 'string';
}

/**
 * The 0-1 score the clustering job produces. A number outside that range is
 * not a confidence this scale can describe — banding it would invent a
 * reading — so it is rejected rather than clamped.
 */
function isConfidenceScore(value: unknown): boolean {
  return isFiniteNumber(value) && value >= 0 && value <= 1;
}

/**
 * A field the API ALWAYS sends but whose value may be null.
 *
 * Deliberately distinct from `isOptional`, which also tolerates the key being
 * absent. These fields are part of the contract: null means "this quantity
 * does not exist for this row" — a supplier with no terminal documents has no
 * touchless rate — whereas a MISSING key means a truncated or wrong payload,
 * which must still be rejected.
 */
function isPresentButNullable(
  container: Record<string, unknown>,
  key: string,
  predicate: (item: unknown) => boolean,
): boolean {
  if (!(key in container)) return false;
  const value = container[key];
  return value === null || predicate(value);
}

/** Every array member must satisfy the predicate; an empty array is valid. */
function isArrayOf<T>(
  value: unknown,
  predicate: (item: unknown) => item is T,
): value is T[] {
  return Array.isArray(value) && value.every(predicate);
}

/**
 * A KPI bucket map: each value carries a numeric count and pct. An empty map is
 * accepted — a period with no documents is a legitimate answer.
 */
export function isValidBucketMap(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  return Object.values(value).every(
    (bucket) =>
      isPlainObject(bucket) &&
      isFiniteNumber(bucket.count) &&
      // `pct` is NULL for IN_PROGRESS and NOT_ELIGIBLE, always: they are not in
      // the rate denominator, so a share of it does not exist for them. The API
      // says so deliberately — "no percentage" and "0 %" are different claims —
      // and requiring a number here rejected EVERY summary response ever sent,
      // for every org, which is what left the KPI tiles reading 0 %.
      //
      // A MISSING pct is still rejected: that is a truncated payload, not a
      // stated absence.
      isPresentButNullable(bucket, 'pct', isFiniteNumber),
  );
}

/** The population block states the denominator, so its numbers must be numbers. */
export function isValidPopulation(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (!isFiniteNumber(value.total) || !isFiniteNumber(value.eligible)) {
    return false;
  }
  const excluded = value.excluded;
  if (!isPlainObject(excluded) || !isFiniteNumber(excluded.count)) return false;
  if (!isPlainObject(excluded.by_reason)) return false;
  return Object.values(excluded.by_reason).every(isFiniteNumber);
}

/** Envelope fields the UI shows verbatim (freshness, contract version). */
export function isValidEnvelope(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (!isNonEmptyString(value.data_as_of)) return false;
  if (!isNonEmptyString(value.metric_contract_version)) return false;
  return isValidPopulation(value.population);
}

function isValidDocTypeOption(value: unknown): boolean {
  return (
    isPlainObject(value) &&
    isNonEmptyString(value.doc_type) &&
    isOptional(value.doc_type_name, isString)
  );
}

function isValidSupplierOption(value: unknown): boolean {
  return (
    isPlainObject(value) &&
    isNonEmptyString(value.supplier_key) &&
    isOptional(value.supplier_name, isString)
  );
}

/**
 * One bar of "where touchless is lost first".
 *
 * `stage` is NULL when the evaluator could not attribute the loss to a stage —
 * the registry's designed UNKNOWN/MEASUREMENT outcome, not an error. On dev
 * that is 16 documents, and requiring a stage name rejected the ENTIRE summary
 * over them: KPI tiles, blocking chart and diagnosis coverage all went blank
 * because one bar of six had no stage.
 *
 * The frontend was already built for this: the store's `undiagnosedCount`
 * counts exactly these entries, and the "Diagnosis coverage" tile exists to
 * report them. `reason_code` carries the meaning when `stage` cannot.
 */
function isValidBlockingStage(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (!isFiniteNumber(value.count)) return false;
  if (!isPresentButNullable(value, 'stage', isNonEmptyString)) return false;
  // `reason_code` is checked whenever it is present, not only on the
  // stage-less branch: the chart calls `.toLowerCase()` on it, so a non-string
  // here throws instead of landing in the panel's error state — a crash is
  // worse than a blank panel, and the guard exists to prevent exactly that.
  if (!isOptional(value.reason_code, isString)) return false;
  // An entry with neither a stage nor a reason says nothing and cannot be
  // labelled — that IS malformed.
  if (value.stage === null && !isNonEmptyString(value.reason_code)) {
    return false;
  }
  return true;
}

export function isValidSummaryResponse(
  value: unknown,
): value is TouchlessSummaryResponse {
  if (!isValidEnvelope(value)) return false;
  const summary = value as Record<string, unknown>;

  if (!isValidBucketMap(summary.buckets)) return false;

  // Both halves are null for an org whose documents are all still in flight —
  // a brand-new org, or one before its first export of the period. That is a
  // legitimate answer ("no rate yet"), not a malformed one, and the tiles show
  // an em dash for it. Only the OBJECT is mandatory.
  const rate = summary.official_touchless_rate;
  if (!isPlainObject(rate)) return false;
  if (!isPresentButNullable(rate, 'pure_pct', isFiniteNumber)) return false;
  if (!isPresentButNullable(rate, 'ap_pct', isFiniteNumber)) return false;

  if (
    !isArrayOf(summary.first_blocking_stages, isValidBlockingStage as never)
  ) {
    return false;
  }

  // available_filters is optional in practice; when present, every MEMBER must
  // be shaped — the filter bar dereferences `option.doc_type_name` and
  // `option.supplier_name`, so a `[null]` here reaches the template.
  const filters = summary.available_filters;
  if (filters !== undefined) {
    if (!isPlainObject(filters)) return false;
    if (
      !isOptional(filters.suppliers, (list) =>
        isArrayOf(list, isValidSupplierOption as never),
      )
    ) {
      return false;
    }
    if (
      !isOptional(filters.doc_types, (list) =>
        isArrayOf(list, isValidDocTypeOption as never),
      )
    ) {
      return false;
    }
  }

  return true;
}

/**
 * A trend point, checked against the arithmetic that produced it.
 *
 * Both rates come from the SAME denominator on the server
 * (`service.py`: `_rate_pct(pure, denominator)` and
 * `_rate_pct(ap, denominator)`), so exactly two shapes are possible:
 *
 *   denominator === 0  ->  both rates null   (no terminal documents that day)
 *   denominator  >  0  ->  both rates numbers
 *
 * Anything else — one null and one number, or nulls with a positive
 * denominator — is arithmetically impossible and therefore corruption. The
 * original guard caught that by requiring numbers; simply allowing null would
 * have thrown the protection away along with the bug, so the check is tied to
 * the denominator instead.
 */
function isValidTrendPoint(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (!isNonEmptyString(value.date)) return false;
  if (!isFiniteNumber(value.denominator)) return false;

  const pure = value.pure_pct;
  const ap = value.ap_pct;
  if (!('pure_pct' in value) || !('ap_pct' in value)) return false;

  if (value.denominator === 0) {
    // A day with nothing terminal. The chart draws a gap here, not a plunge.
    return pure === null && ap === null;
  }
  return isFiniteNumber(pure) && isFiniteNumber(ap);
}

export function isValidTrendResponse(
  value: unknown,
): value is TouchlessTrendResponse {
  if (!isValidEnvelope(value)) return false;
  return isArrayOf(
    (value as Record<string, unknown>).points,
    isValidTrendPoint as never,
  );
}

/**
 * Every column SupplierQueueTable renders. Validating only the first three
 * accepted a row that then printed "undefined" in seven cells.
 */
function isValidSupplierRow(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (!isNonEmptyString(value.supplier_key)) return false;
  if (!isNonEmptyString(value.supplier_name)) return false;
  if (!isFiniteNumber(value.volume)) return false;
  if (!isFiniteNumber(value.lost_docs)) return false;
  if (!isFiniteNumber(value.recoverable_docs)) return false;
  // The API cannot calculate a lift while every document is still in flight:
  // the eligible denominator is zero, so null is the honest value. It must
  // still be present — a missing field is a malformed row.
  if (!isPresentButNullable(value, 'expected_lift_pct', isFiniteNumber)) {
    return false;
  }
  if (!isNonEmptyString(value.status)) return false;
  if (!isOptional(value.top_issue_signature, isString)) return false;

  // The three fields a supplier can legitimately have no answer for. On dev,
  // 20 of 25 rows carry null in all three — suppliers whose documents are all
  // still in flight, which is the normal state for most of them. Requiring
  // values rejected the entire queue, including the four suppliers that DID
  // have a diagnosis and were the point of the report.
  //
  //  * pure_pct           — no terminal documents, so no rate exists
  //  * root_cause_domain  — no cluster yet, so no dominant cause is known
  //  * confidence         — comes from that same absent cluster
  if (!isPresentButNullable(value, 'pure_pct', isFiniteNumber)) return false;
  // Non-empty or null: an empty string would render as a blank cell that is
  // indistinguishable from "no cause known", while meaning something went
  // wrong upstream.
  if (!isPresentButNullable(value, 'root_cause_domain', isNonEmptyString)) {
    return false;
  }
  // A 0-1 score from the clustering job, not a label. `isString` here rejected
  // every row the API has ever sent.
  if (!isPresentButNullable(value, 'confidence', isConfidenceScore)) {
    return false;
  }
  return true;
}

export function isValidSupplierListResponse(
  value: unknown,
): value is TouchlessSupplierOpportunitiesResponse {
  if (!isValidEnvelope(value)) return false;
  const page = value as Record<string, unknown>;
  if (!isFiniteNumber(page.element_count)) return false;
  return isArrayOf(page.data, isValidSupplierRow as never);
}

/**
 * An internal route the UI may turn into a link.
 *
 * Exported because two different things need the SAME answer: the fix-step
 * list, which decides whether to render a button, and the tests, which pin the
 * rule. A component that re-implemented it would drift.
 *
 * Fix-step routes are authored by the backend today and, once the advisor
 * ships, ultimately by a language model. So the rule is a whitelist of shape,
 * not a blacklist of known-bad strings:
 *
 *  * must be a same-origin PATH: starts with `/`, never `//` (which the
 *    browser reads as a protocol-relative URL to another host)
 *  * no scheme: a `:` anywhere before the query or fragment rejects
 *    `javascript:alert(1)`, `https://evil` and `mailto:`
 *  * no `..` segment, so `/settings/../login` cannot walk out of settings
 *  * no whitespace, control character or backslash — all of which browsers and
 *    routers normalise differently, which is how a "safe" string becomes an
 *    unsafe one between the check and the navigation
 *  * a sane length, because the value ends up in the DOM
 *
 * The EXACT string is judged, untrimmed: the value that is checked has to be
 * the value that is used, or the check describes something else.
 */
export function isSafeInternalRoute(value: unknown): value is string {
  if (typeof value !== 'string') return false;
  if (value.length === 0 || value.length > 512) return false;
  if (!value.startsWith('/')) return false;
  // Protocol-relative: `//evil.example/x` is a different HOST, not a path.
  if (value.startsWith('//')) return false;
  // Whitespace (incl. the leading space that makes ' /x' not start with '/'),
  // backslash, and C0/C1 control characters.
  // eslint-disable-next-line no-control-regex
  if (/[\s\\\u0000-\u001f\u007f]/.test(value)) return false;

  const markerIndex = value.search(/[?#]/);
  const path = markerIndex === -1 ? value : value.slice(0, markerIndex);
  // A scheme separator in the PATH only. `/x?a=b:c` is a legitimate query.
  if (path.includes(':')) return false;
  if (path.split('/').includes('..')) return false;
  return true;
}

/**
 * One step of "what to change".
 *
 * Every member is optional — the advisor may omit `what` on a one-line step,
 * and `route` is null whenever no screen carries the change. But a step with
 * NEITHER a label nor a description says nothing and cannot be rendered, which
 * is malformed rather than empty. (Same rule as `isValidBlockingStage`: an
 * entry that cannot be labelled is rejected, not drawn blank.)
 *
 * "Says nothing" is judged on TRIMMED content: `{label: "   "}` renders as a
 * numbered bullet with a blank beside it, which is the very outcome the check
 * exists to prevent, and a model that pads its output is exactly the source
 * these steps come from.
 */
export function isValidFixStep(value: unknown): boolean {
  if (!isWellTypedFixStep(value)) return false;
  const step = value as Record<string, unknown>;
  // `text` counts as prose (DOCB-14285). The advisor's own schema names the
  // sentence `text`, the deterministic path names it `label`, and dev served
  // `{text, route}` for every AI-generated step. A step that says something is
  // renderable whichever key it arrived under — `TouchlessFixStepList`
  // promotes it to the label exactly as it promotes a lone `what`.
  return hasText(step.label) || hasText(step.what) || hasText(step.text);
}

/**
 * The part of a step that is a TYPE question rather than a content question.
 *
 * Split out of `isValidFixStep` because the two answers deserve different
 * consequences (DOCB-14285). A step whose `route` is a number reaches a `:to`
 * binding and a step whose `label` is an object prints "[object Object]" — the
 * payload is not what it claims to be, and rejecting it is right. But a step
 * that is merely EMPTY says nothing and renders as nothing; `renderableSteps`
 * already drops it. Answering that with "Failed to load" for the whole
 * supplier diagnosis threw away the cause, the owner, the evidence and every
 * other step to avoid one blank bullet — which is exactly how a `{text, route}`
 * contract drift became a dead page for every supplier with AI advice.
 */
function isWellTypedFixStep(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (!isOptional(value.route, isString)) return false;
  if (!isOptional(value.label, isString)) return false;
  if (!isOptional(value.what, isString)) return false;
  if (!isOptional(value.text, isString)) return false;
  return true;
}

/** An optional array whose every member must satisfy the predicate. */
function isOptionalArrayOf(
  value: unknown,
  predicate: (item: unknown) => boolean,
): boolean {
  return isOptional(value, (list) => isArrayOf(list, predicate as never));
}

/**
 * The advisor block on a cluster (backend PR-B2).
 *
 * Tolerant by design: the endpoint ships before the advisor does, a failed run
 * leaves `last_error` and nothing else, and a human-confirmed row carries
 * different members from a generated one. Requiring any single field would
 * turn each of those legitimate states into "Failed to load" for the WHOLE
 * supplier diagnosis.
 *
 * What is still enforced is type, because these values reach the template:
 * `missing_evidence` is iterated, `confidence` is banded arithmetically, and
 * `fix_steps[].route` becomes a link target.
 */
export function isValidAdvice(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (!isOptional(value.provenance, isString)) return false;
  if (!isOptional(value.confidence, isConfidenceScore)) return false;
  if (!isOptional(value.hypothesis, (flag) => typeof flag === 'boolean')) {
    return false;
  }
  if (!isOptional(value.language, isString)) return false;
  if (!isOptional(value.model, isString)) return false;
  if (!isOptional(value.prompt_version, isString)) return false;
  if (!isOptional(value.generated_at, isString)) return false;
  if (!isOptional(value.data_as_of, isString)) return false;
  if (!isOptional(value.status, isString)) return false;
  if (!isOptional(value.last_error, isString)) return false;
  if (!isOptional(value.confirmed_cause, isString)) return false;
  if (!isOptional(value.evidence_summary, isString)) return false;
  if (!isOptional(value.owner, isString)) return false;
  if (!isOptional(value.owner_label, isString)) return false;
  if (!isOptionalArrayOf(value.open_questions, isString)) return false;
  if (!isOptionalArrayOf(value.missing_evidence, isString)) return false;
  // Type-checked, not content-checked (DOCB-14285): an empty step is dropped
  // at render time, so it must not cost the reader the whole response.
  if (!isOptionalArrayOf(value.fix_steps, isWellTypedFixStep)) return false;
  return true;
}

/**
 * Every field IssueClusterCard renders. A member that is present but of the
 * wrong type would reach the template and either throw or print "[object
 * Object]" next to a real cause, which is worse than an honest error state.
 */
function isValidIssue(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (!isNonEmptyString(value.issue_signature)) return false;
  // `stage`, as the API names it — the same key the summary's
  // `first_blocking_stages[]` entries use. This guard used to require
  // `first_blocking_stage`, a key no cluster the API has ever sent carries, so
  // every supplier diagnosis on dev was refused as malformed while the API
  // answered 200 with correct data. (`first_blocking_stage` is the DOCUMENT
  // level field, on outcomes and recent examples; a cluster has a `stage`.)
  //
  // Null for a cluster whose loss could not be attributed to a stage — 4 of 26
  // on dev.
  if (!isPresentButNullable(value, 'stage', isNonEmptyString)) {
    return false;
  }
  if (!isFiniteNumber(value.affected_doc_count)) return false;
  if (!isFiniteNumber(value.recoverable_doc_count)) return false;
  if (!isFiniteNumber(value.potential_pure_lift_pct)) return false;
  if (!isOptional(value.reason_code, isString)) return false;
  if (!isOptional(value.domain, isString)) return false;
  if (!isOptional(value.confirmed_cause, isString)) return false;
  if (!isOptional(value.evidence_summary, isString)) return false;
  if (!isOptional(value.fixability_code, isString)) return false;
  if (!isOptional(value.owner, isString)) return false;
  if (!isOptional(value.status, isString)) return false;
  // Sent TODAY as 'DETERMINISTIC' on every cluster; still optional, because a
  // guard that requires it would reject the payload the moment the backend
  // adds a cluster kind that has no provenance yet.
  if (!isOptional(value.provenance, isString)) return false;
  if (!isOptional(value.owner_label, isString)) return false;
  // Type-checked, not content-checked (DOCB-14285): an empty step is dropped
  // at render time, so it must not cost the reader the whole response.
  if (!isOptionalArrayOf(value.fix_steps, isWellTypedFixStep)) return false;
  // Absent and null are both "no advice for this cluster" — the state every
  // cluster is in until the advisor has run, and the state a fail-open advisor
  // leaves behind. A MALFORMED advice object is still rejected: it reaches the
  // template, where `missing_evidence` is iterated and `fix_steps[].route`
  // becomes a link.
  if (!isOptional(value.advice, isValidAdvice)) return false;
  // Numeric 0-1 score, same as on the supplier row — not a label.
  if (!isOptional(value.confidence, isConfidenceScore)) return false;
  if (
    !isOptional(value.sample_doc_ids, (ids) =>
      isArrayOf(ids, isString as never),
    )
  ) {
    return false;
  }
  return true;
}

/**
 * Recent examples are mapped straight to `doc_id`; a `[null]` member used to
 * pass the array check and then throw on `.map` in the detail page.
 */
function isValidRecentExample(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (!isNonEmptyString(value.doc_id)) return false;
  // DOCB-14458: the filename and the supplier are optional on purpose. The
  // document can be gone (13 of 1367 outcome rows on the reporting
  // environment), and a supplier grouped only by name has no id, so a null
  // here is data rather than a malformed payload — `isOptional` already
  // accepts it.
  if (!isOptional(value.doc_name, isString)) return false;
  if (!isOptional(value.supplier_id, isString)) return false;
  if (!isOptional(value.supplier_name, isString)) return false;
  if (!isOptional(value.kpi_bucket, isString)) return false;
  if (!isOptional(value.first_blocking_stage, isString)) return false;
  if (!isOptional(value.first_blocking_reason_code, isString)) return false;
  if (!isOptional(value.doc_created_on, isString)) return false;
  return true;
}

export function isValidDiagnosisResponse(
  value: unknown,
): value is TouchlessSupplierDiagnosisResponse {
  if (!isValidEnvelope(value)) return false;
  const diagnosis = value as Record<string, unknown>;
  if (!isNonEmptyString(diagnosis.supplier_key)) return false;
  if (!isValidBucketMap(diagnosis.buckets)) return false;
  if (!isNonEmptyString(diagnosis.supplier_name)) return false;
  if (!isArrayOf(diagnosis.issues, isValidIssue as never)) return false;
  if (
    !isOptional(diagnosis.recent_examples, (examples) =>
      isArrayOf(examples, isValidRecentExample as never),
    )
  ) {
    return false;
  }
  return true;
}

/**
 * Every field the timeline reads. `detail` is rendered key-by-key, so it has to
 * be an object (or absent) — an array or a string there would print nonsense.
 */
function isValidTraceStage(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (!isNonEmptyString(value.stage)) return false;
  // Status drives the colour and icon. Unknown values are rendered raw by
  // design, so any non-empty string is accepted — but it must be a string.
  if (!isNonEmptyString(value.status)) return false;
  if (!isOptional(value.attempt, isFiniteNumber)) return false;
  if (!isOptional(value.reason_code, isString)) return false;
  if (!isOptional(value.detail, isPlainObject)) return false;
  if (!isOptional(value.duration_ms, isFiniteNumber)) return false;
  if (!isOptional(value.source, isString)) return false;
  return true;
}

function isValidTraceEvidence(value: unknown): boolean {
  return isPlainObject(value) && isNonEmptyString(value.evidence_type);
}

/**
 * `trigger`, `outcome`, `started_at` and `is_human_trigger` are required, not
 * optional: the run header renders all four. A run of only {run_seq, stages}
 * used to pass and then render an untitled card with an empty outcome chip.
 */
function isValidTraceRun(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (!isFiniteNumber(value.run_seq)) return false;
  if (!isArrayOf(value.stages, isValidTraceStage as never)) return false;
  if (!isNonEmptyString(value.trigger)) return false;
  if (!isNonEmptyString(value.outcome)) return false;
  if (!isNonEmptyString(value.started_at)) return false;
  if (typeof value.is_human_trigger !== 'boolean') return false;
  if (!isOptional(value.ended_at, isString)) return false;
  if (
    !isOptional(value.evidence, (items) =>
      isArrayOf(items, isValidTraceEvidence as never),
    )
  ) {
    return false;
  }
  return true;
}

/**
 * The document-level facts the trace header renders. This is the API's
 * `outcome` object — the serialised outcome row — not a flattened response.
 */
function isValidTraceOutcome(value: unknown): boolean {
  if (!isPlainObject(value)) return false;
  if (!isNonEmptyString(value.doc_id)) return false;
  if (typeof value.human_touched !== 'boolean') return false;
  if (!isNonEmptyString(value.kpi_bucket)) return false;
  if (!isOptional(value.first_blocking_stage, isString)) return false;
  if (!isOptional(value.supplier_key, isString)) return false;
  if (!isOptional(value.supplier_name, isString)) return false;
  return true;
}

/**
 * The trace response is `{outcome, runs}` plus the envelope: the outcome row
 * under `outcome`, the runs beside it. This guard used to expect `doc_id`,
 * `kpi_bucket` and `human_touched` at the TOP level — a shape the API has never
 * produced — so every document trace on dev was refused as malformed.
 *
 * The population block is not checked: for one document it is trivially
 * `{total: 1}` and nothing on the page reads it.
 */
export function isValidTraceResponse(
  value: unknown,
): value is TouchlessDocumentTraceResponse {
  if (!isPlainObject(value)) return false;
  if (!isNonEmptyString(value.data_as_of)) return false;
  if (!isValidTraceOutcome(value.outcome)) return false;
  return isArrayOf(value.runs, isValidTraceRun as never);
}

/**
 * The org target comes from the API. Only a real percentage is trusted; a
 * missing, non-numeric or out-of-range value falls back to the documented
 * default so the delta colouring and the chart annotation never disappear.
 */
export function resolveTargetPct(
  value: unknown,
  fallback: number = TOUCHLESS_DEFAULT_TARGET_PCT,
): number {
  if (!isFiniteNumber(value)) return fallback;
  if (value < 0 || value > 100) return fallback;
  return value;
}

/** Evidence doc ids are `documents.id` UUIDs; anything else is not linkable. */
const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Judges the EXACT string, without trimming. The trimmed form used to pass
 * while the untrimmed value went into the route and the request — a padded id
 * validated fine and then 404'd. Callers that genuinely need to accept padding
 * should normalise first with `normalizeDocumentId`.
 */
export function isDocumentId(value: unknown): value is string {
  return typeof value === 'string' && UUID_RE.test(value);
}

/** Trims and validates, returning the canonical id or null. */
export function normalizeDocumentId(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  return UUID_RE.test(trimmed) ? trimmed : null;
}
